div.script:
var bannerId = 'holiday_banner';

var startDate = 1788548400;
var endDate = 1788872399;

// javascript epoch uses milliseconds, php does not, 
// so divide by 1000 and remove decimals
var now = new Date().getTime() / 1000 | 0;

if (now >= startDate && now <= endDate) { // hide if before start or after end
	document.getElementById(bannerId).style.display = "block";
}

